create function public.novacart_embedding_batch() returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('entries',coalesce(jsonb_agg(jsonb_build_object('id',id,'text',title||': '||content) order by id),'[]')) from public.novacart_knowledge where embedding is null $$;
create function public.novacart_save_embeddings(p jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$ declare e jsonb; n int:=0; begin for e in select value from jsonb_array_elements(p) loop update public.novacart_knowledge set embedding=(e->>'embedding')::extensions.vector,embedding_model='text-embedding-3-small' where id=e->>'id'; n:=n+1; end loop; return jsonb_build_object('updated',n); end $$;
create function public.novacart_retrieve(query_embedding extensions.vector(1536)) returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('policies',coalesce(jsonb_agg(k),'[]'),'retrieval_mode','semantic') from public.novacart_match_knowledge(query_embedding,8) k where similarity>0.15 $$;
revoke all on function public.novacart_embedding_batch,public.novacart_save_embeddings from public,anon,authenticated; grant execute on function public.novacart_embedding_batch,public.novacart_save_embeddings to service_role;
revoke all on function public.novacart_retrieve from public,anon; grant execute on function public.novacart_retrieve to authenticated,service_role;
